function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const words = ['A', 'Item', 'Pro', 'x', 'Model', '-', ' ', 'Box', 'v', '.'];
  const count = small ? pick(9) : 1500 + pick(501);
  const ids = [];
  for (let id = 1; id <= (small ? 12 : 4000); id++) ids.push(id);
  for (let i = ids.length - 1; i > 0; i--) { const j = pick(i + 1); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const products = [];
  for (const id of ids.slice(0, count)) {
    // A name alternates words and digit runs of 1 to 5 digits, so runs of exactly three are common but not certain.
    const parts = 1 + pick(4);
    let name = '', digits = rand() < 0.5;
    for (let k = 0; k < parts; k++, digits = !digits) {
      if (digits) { const length = 1 + pick(5); for (let d = 0; d < length; d++) name += String(pick(10)); }
      else name += words[pick(words.length)];
    }
    products.push([id, name]);
  }
  return [{ products }];
}
